const rankingsLeaderboard = `-- name: RankingsLeaderboard :many
WITH deduped AS (
    SELECT DISTINCT ON (edr.player_guid, edr.encounter_name, COALESCE(li.duplicate_group_id, li.id))
        edr.id,
        edr.encounter_name,
        edr.instance_name,
        edr.player_guid,
        edr.player_name,
        edr.player_class,
        edr.player_spec,
        edr.player_role,
        edr.player_level,
        edr.difficulty_name,
        edr.max_players,
        edr.realm_id,
        edr.realm_name,
        edr.guild_name,
        edr.damage_done,
        edr.duration_secs,
        edr.dps,
        edr.avg_ilvl,
        edr.log_hashed_slug,
        edr.killed_at,
        tb.sub_spec AS talent_sub_spec
    FROM encounter_dps_rankings edr
    JOIN log_instances li ON li.id = edr.instance_id
    JOIN wow_server_realms wsr ON wsr.id = edr.realm_id
    LEFT JOIN talent_builds tb ON tb.id = edr.talent_build_id
    WHERE CASE
        WHEN cardinality($3 :: text[]) > 0 THEN edr.instance_name = ANY($3 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($4 :: text[]) > 0 THEN edr.encounter_name = ANY($4 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $5 :: text != '' THEN edr.realm_id = $5 :: uuid
        ELSE true
    END
    AND CASE
        WHEN $6 :: text != '' THEN edr.player_class = $6
        ELSE true
    END
    AND CASE
        WHEN $7 :: text != '' THEN edr.player_spec = $7
        ELSE true
    END
    AND CASE
        WHEN $8 :: text != '' THEN edr.player_role = $8
        ELSE true
    END
    AND CASE
        WHEN $9 :: bigint > 0 THEN edr.killed_at >= now() - make_interval(days => $9::int)
        ELSE true
    END
    ORDER BY edr.player_guid, edr.encounter_name, COALESCE(li.duplicate_group_id, li.id), edr.dps DESC
)
SELECT
    d.id, d.encounter_name, d.instance_name, d.player_guid, d.player_name, d.player_class, d.player_spec, d.player_role, d.player_level, d.difficulty_name, d.max_players, d.realm_id, d.realm_name, d.guild_name, d.damage_done, d.duration_secs, d.dps, d.avg_ilvl, d.log_hashed_slug, d.killed_at, d.talent_sub_spec,
    COUNT(*) OVER() AS total_count
FROM deduped d
ORDER BY d.dps DESC
LIMIT $2::bigint
OFFSET $1::bigint
`

